export const getGetNetworkUrl = (params?: GetNetworkParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/network?${stringifiedParams}` : `/api/network`
}

/**
 * @summary Criminal network graph (nodes and edges)
 */
export const getNetwork = async (params?: GetNetworkParams, options?: RequestInit): Promise<NetworkGraph> => {

  return customFetch<NetworkGraph>(getGetNetworkUrl(params),
  {
    ...options,
    method: 'GET'


  }
);}





